/**
 * Drizzle schema for the team's Supabase tables (public schema).
 * Generated with `npx drizzle-kit pull` from the live database, trimmed to the
 * tables personalization uses. Supabase is the source of truth and is managed
 * by the team: NEVER run drizzle-kit generate/migrate/push against it. To pick
 * up schema changes, re-run `npx drizzle-kit pull` and copy the tables here.
 *
 * Hand-typed (drizzle-kit can't parse them):
 *  - geography(Point,4326): read as the raw WKB hex string; write with
 *    sql`ST_SetSRID(ST_MakePoint(lng, lat), 4326)::geography`.
 *  - tsvector: generated by the DB, never written.
 */
import { sql } from "drizzle-orm";
import {
  boolean, check, customType, foreignKey, index, integer, jsonb, pgTable, text, timestamp, unique, uuid,
} from "drizzle-orm/pg-core";

const geographyPoint = customType<{ data: string }>({ dataType: () => "geography(Point,4326)" });
const tsvector = customType<{ data: string }>({ dataType: () => "tsvector" });

export const resources = pgTable("resources", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	slug: text().notNull(),
	name: text().notNull(),
	description: text().notNull(),
	category: text().notNull(),
	subcategory: text(),
	addressLine: text("address_line"),
	city: text().default('Calgary'),
	postalCode: text("postal_code"),
	location: geographyPoint("location").notNull(),
	costType: text("cost_type").notNull(),
	costNotes: text("cost_notes"),
	ageMinMonths: integer("age_min_months"),
	ageMaxMonths: integer("age_max_months"),
	eligibilitySummary: text("eligibility_summary"),
	eligibilityRequirements: text("eligibility_requirements").array(),
	languages: text().array().default(["en"]),
	phone: text(),
	email: text(),
	website: text(),
	sourceUrl: text("source_url").notNull(),
	lastVerifiedAt: timestamp("last_verified_at", { withTimezone: true, mode: 'string' }).notNull(),
	verifiedBy: text("verified_by"),
	isActive: boolean("is_active").default(true).notNull(),
	searchTsv: tsvector("search_tsv").generatedAlwaysAs(sql`to_tsvector('english'::regconfig, ((((COALESCE(name, ''::text) || ' '::text) || COALESCE(description, ''::text)) || ' '::text) || COALESCE(eligibility_summary, ''::text)))`),
	createdAt: timestamp("created_at", { withTimezone: true, mode: 'string' }).defaultNow(),
	updatedAt: timestamp("updated_at", { withTimezone: true, mode: 'string' }).defaultNow(),
	startsAt: timestamp("starts_at", { withTimezone: true, mode: 'string' }),
	endsAt: timestamp("ends_at", { withTimezone: true, mode: 'string' }),
	schedule: text().array().default(sql`'{}'::text[]`).notNull(),
}, (table) => [
	index("resources_active_category_idx").using("btree", table.isActive.asc().nullsLast().op("text_ops"), table.category.asc().nullsLast().op("text_ops")),
	index("resources_category_idx").using("btree", table.category.asc().nullsLast().op("text_ops")),
	index("resources_location_idx").using("gist", table.location.asc().nullsLast().op("gist_geography_ops")),
	index("resources_schedule_idx").using("gin", table.schedule.asc().nullsLast().op("array_ops")),
	index("resources_search_tsv_idx").using("gin", table.searchTsv.asc().nullsLast().op("tsvector_ops")),
	index("resources_starts_at_idx").using("btree", table.startsAt.asc().nullsLast().op("timestamptz_ops")),
	unique("resources_slug_key").on(table.slug),
	check("resources_age_range_check", sql`(age_min_months IS NULL) OR (age_max_months IS NULL) OR (age_min_months <= age_max_months)`),
	check("resources_category_check", sql`category = ANY (ARRAY['childcare'::text, 'financial'::text, 'housing'::text, 'food'::text, 'health_family'::text, 'community'::text, 'activities'::text, 'legal_info'::text])`),
	check("resources_cost_type_check", sql`cost_type = ANY (ARRAY['free'::text, 'subsidized'::text, 'income_based'::text, 'paid'::text])`),
	check("resources_event_dates_check", sql`(ends_at IS NULL) OR ((starts_at IS NOT NULL) AND (ends_at >= starts_at))`),
	check("resources_schedule_values_check", sql`schedule <@ ARRAY['evenings'::text, 'overnight'::text, 'weekends'::text, 'drop_in'::text]`),
]);

export const users = pgTable("users", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	auth0Sub: text("auth0_sub").notNull(),
	email: text(),
	displayName: text("display_name"),
	role: text().default('user').notNull(),
	rulesAcceptedAt: timestamp("rules_accepted_at", { withTimezone: true, mode: 'string' }),
	createdAt: timestamp("created_at", { withTimezone: true, mode: 'string' }).defaultNow(),
}, (table) => [
	unique("users_auth0_sub_key").on(table.auth0Sub),
	unique("users_display_name_key").on(table.displayName),
	check("users_role_check", sql`role = ANY (ARRAY['user'::text, 'admin'::text])`),
]);

export const userPreferences = pgTable("user_preferences", {
	userId: uuid("user_id").primaryKey().notNull(),
	postalFsa: text("postal_fsa"),
	approxLocation: geographyPoint("approx_location"),
	childAgeBands: text("child_age_bands").array(),
	categories: text().array(),
	budgetBand: text("budget_band"),
	language: text().default('en').notNull(),
	updatedAt: timestamp("updated_at", { withTimezone: true, mode: 'string' }).defaultNow(),
}, (table) => [
	foreignKey({
			columns: [table.userId],
			foreignColumns: [users.id],
			name: "user_preferences_user_id_fkey"
		}).onDelete("cascade"),
	check("user_preferences_postal_fsa_check", sql`(postal_fsa IS NULL) OR (char_length(postal_fsa) = 3)`),
]);

export const supportPlans = pgTable("support_plans", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	userId: uuid("user_id").notNull(),
	criteria: jsonb(),
	createdAt: timestamp("created_at", { withTimezone: true, mode: 'string' }).defaultNow(),
}, (table) => [
	index("support_plans_user_created_idx").using("btree", table.userId.asc().nullsLast().op("timestamptz_ops"), table.createdAt.desc().nullsFirst().op("timestamptz_ops")),
	foreignKey({
			columns: [table.userId],
			foreignColumns: [users.id],
			name: "support_plans_user_id_fkey"
		}).onDelete("cascade"),
]);

export const planActions = pgTable("plan_actions", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	planId: uuid("plan_id").notNull(),
	resourceId: uuid("resource_id"),
	title: text().notNull(),
	reason: text().notNull(),
	firstStep: text("first_step").notNull(),
	priority: integer().notNull(),
	status: text().default('todo').notNull(),
	completedAt: timestamp("completed_at", { withTimezone: true, mode: 'string' }),
}, (table) => [
	index("plan_actions_plan_priority_idx").using("btree", table.planId.asc().nullsLast().op("int4_ops"), table.priority.asc().nullsLast().op("int4_ops")),
	foreignKey({
			columns: [table.planId],
			foreignColumns: [supportPlans.id],
			name: "plan_actions_plan_id_fkey"
		}).onDelete("cascade"),
	foreignKey({
			columns: [table.resourceId],
			foreignColumns: [resources.id],
			name: "plan_actions_resource_id_fkey"
		}).onDelete("set null"),
	check("plan_actions_priority_check", sql`priority >= 0`),
	check("plan_actions_status_check", sql`status = ANY (ARRAY['todo'::text, 'done'::text])`),
]);

export type Resource = typeof resources.$inferSelect;
export type NewResource = typeof resources.$inferInsert;
